package com.trombokendu.chronos.ingest;import java.nio.file.*;import java.nio.charset.*;import java.time.*;import java.util.*;import com.trombokendu.chronos.domain.*;public final class CsvStatementParser extends StatementParser{public List<LedgerEvent> parse(Path f){List<LedgerEvent> out=new ArrayList<>();try{List<String> lines=Files.readAllLines(f,StandardCharsets.UTF_8);for(int i=1;i<lines.size();i++){String[] x=lines.get(i).split(",",5);if(x.length<5)continue;String row=lines.get(i);UUID id=UUID.nameUUIDFromBytes(row.getBytes(StandardCharsets.UTF_8));out.add(new TransactionPosted(id,Instant.now(),LocalDate.parse(x[0]),Kind.valueOf(x[1].trim().toUpperCase(Locale.ROOT)),Category.fromDisplay(x[2].trim()),Money.of(x[3].trim()),x[4],Optional.empty(),Optional.empty()));}return out;}catch(Exception e){throw new ValidationException("CSV parse failed: "+e.getMessage(),e);}}}
